from django import template
from django.template.defaulttags import url
from django.urls import reverse
from django.utils.safestring import mark_safe

register = template.Library()


class LogInOutNode(template.Node):
    def __init__(self, bool):
        self.bool = bool

    def render(self, context):
        request = template.Variable('request')(context)
        if request.user.is_authenticated:
            text = 'Log out'
        else:
            text = 'Log in'
        if self.bool:
            return text
        else:
            return reverse('salesforce:login')


@register.tag()
def log_in_out(parser, token):
    '''
    Returns 'Log in' or 'Log out' depending on
    whether you are logged in or not. If you're
    not logged in, it'll return the 'Log in' link
    '''
    args = token.split_contents()
    if len(args) != 1:
        raise template.TemplateSyntaxError('log_in_out tag must be called as {% log_in_out [pure text] %}')
    return LogInOutNode(True)


class AppImageNode(template.Node):
    def __init__(self, app_name):
        self.app_name = app_name

    def render(self, context):
        return reverse('salesforce:app_image', args=(self.app_name,))


@register.tag()
def app_image(parser, token):
    '''
    Returns the image for the app specified.
    '''
    args = token.split_contents()
    if len(args) != 2:
        raise template.TemplateSyntaxError('app_image tag must be called as {% app_image "app_name" %}')
    return AppImageNode(template.Variable(args[1]))


class AppRedirectNode(template.Node):
    def __init__(self, response, status_code):
        self.response = response
        self.status_code = status_code

    def render(self, context):
        return mark_safe('<meta http-equiv="refresh" content="3; url=%s"%s>' % (
            self.response, self.status_code))


@register.tag()
def app_redirect(parser, token):
    '''
    Redirects to another page. You can specify the
    status code if you want (default is 200).
    '''
    args = token.split_contents()
    if len(args) not in (2, 3):
        raise template.TemplateSyntaxError('app_redirect tag must be called as {% app_redirect "url" [status code] %}')
    return AppRedirectNode(template.Variable(args[1]), args[2] if len(args) == 3 else ' status="302"')


